{"implementation":"def solve(case):
    import math

    payload = case
    if isinstance(case, dict) and "payload" in case:
        payload = case["payload"]
    if not isinstance(payload, dict):
        raise ValueError("case must be an object")

    required = ("nodes", "core_distance", "distances")
    if any(name not in payload for name in required):
        raise ValueError("missing required field")

    nodes = payload["nodes"]
    core_distance = payload["core_distance"]
    distances = payload["distances"]
    if not isinstance(nodes, list) or not isinstance(core_distance, dict) or not isinstance(distances, list):
        raise ValueError("invalid field type")
    if any(not isinstance(node, str) for node in nodes) or len(set(nodes)) != len(nodes):
        raise ValueError("nodes must be unique strings")
    if set(core_distance) != set(nodes):
        raise ValueError("core distances must match nodes")

    def number(value):
        return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)

    for node in nodes:
        value = core_distance[node]
        if not number(value) or value < 0:
            raise ValueError("invalid core distance")

    node_set = set(nodes)
    seen = set()
    edges = []
    for item in distances:
        if not isinstance(item, (list, tuple)) or len(item) != 3:
            raise ValueError("invalid distance entry")
        left, right, distance = item
        if left not in node_set or right not in node_set or left == right:
            raise ValueError("invalid distance endpoint")
        if not number(distance) or distance < 0:
            raise ValueError("invalid distance")
        a, b = (left, right) if left < right else (right, left)
        pair = (a, b)
        if pair in seen:
            raise ValueError("duplicate undirected distance")
        seen.add(pair)
        weight = max(core_distance[a], core_distance[b], distance)
        edges.append((weight, a, b, distance))

    edges.sort(key=lambda edge: (edge[0], edge[1], edge[2]))
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    selected = []
    for weight, left, right, distance in edges:
        root_left = find(left)
        root_right = find(right)
        if root_left == root_right:
            continue
        if rank[root_left] < rank[root_right]:
            root_left, root_right = root_right, root_left
        parent[root_right] = root_left
        if rank[root_left] == rank[root_right]:
            rank[root_left] += 1
        selected.append({"left": left, "right": right, "weight": weight})
        if len(selected) == len(nodes) - 1:
            break

    if len(selected) != max(0, len(nodes) - 1):
        raise ValueError("disconnected input")
    total_weight = sum(edge["weight"] for edge in selected)
    return {"edges": selected, "total_weight": total_weight}
